import os
from openai import OpenAI


def get_openai_client(api_key=None):
    api_key = api_key or os.environ.get('OPENAI_API_KEY')
    if not api_key:
        raise ValueError("OpenAI API key not found. Please set OPENAI_API_KEY environment variable or pass it directly.")
    return OpenAI(api_key=api_key)

from typing import List, Dict, Any


def normalize_embedding_response(response: Any) -> List[Dict[str, Any]]:
    # Assuming response.data is a list of embedding objects
    # Each object has an 'embedding' attribute and potentially other info
    return [{'embedding': item.embedding} for item in response.data]


def prepare_batch_payload(texts: List[str], model: str = 'text-embedding-3-small') -> Dict[str, Any]:
    return {'input': texts, 'model': model}


def prepare_text_payload(text: str, model: str = 'text-embedding-3-small') -> Dict[str, Any]:
    return {'input': text, 'model': model}

import os
from openai import OpenAI
from typing import List, Dict, Any

def embedding_job_summary(job_results: List[Dict[str, Any]], config: Dict[str, Any] = None) -> Dict[str, str]:
    config = config or {}
    api_key = config.get('api_key') or os.environ.get('OPENAI_API_KEY')
    if not api_key:
        raise ValueError("OpenAI API key not found. Please set OPENAI_API_KEY environment variable or pass it directly.")

    client = OpenAI(api_key=api_key)

    # Prepare the content to summarize
    # For simplicity, we'll stringify the results. In a real scenario, you'd process these more intelligently.
    content_to_summarize = "\n".join([str(result) for result in job_results])

    try:
        response = client.chat.completions.create(
            model="gpt-3.5-turbo",  # Using a common summarization model
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes embedding job results."},
                {"role": "user", "content": f"Summarize the following embedding job results:\n\n{content_to_summarize}"}
            ]
        )
        summary = response.choices[0].message.content
        return {'summary': summary}
    except Exception as e:
        return {'error': str(e)}

import os
from google.cloud import language_v1
from typing import List, Dict, Any

def corpus_safety(texts: List[str], config: Dict[str, Any] = None) -> Dict[str, Any]:
    config = config or {}
    # Google Cloud project ID can be set via GOOGLE_CLOUD_PROJECT environment variable
    # or explicitly passed in config.
    # For this example, we assume GOOGLE_APPLICATION_CREDENTIALS is set up.

    client = language_v1.LanguageServiceClient()
    results = []

    for i, text_content in enumerate(texts):
        document = language_v1.Document(content=text_content, type_=language_v1.Document.Type.PLAIN_TEXT)

        try:
            # Performing sentiment analysis as a basic safety check. 
            # A dedicated content moderation API would be more robust for 'safety'.
            sentiment = client.analyze_sentiment(request={'document': document}).document_sentiment
            results.append({
                'text_index': i,
                'text': text_content,
                'sentiment_score': sentiment.score,
                'sentiment_magnitude': sentiment.magnitude,
                'is_safe': sentiment.score >= -0.2  # Simple heuristic: consider safe if not strongly negative
            })
        except Exception as e:
            results.append({
                'text_index': i,
                'text': text_content,
                'error': str(e),
                'is_safe': False
            })

    return {'safety_results': results}

import os
from google.cloud import translate_v2 as translate
from typing import List, Dict, Any

def multilingual_query_translate(queries: List[str], target_language: str, config: Dict[str, Any] = None) -> Dict[str, Any]:
    config = config or {}
    # Google Cloud project ID and credentials assumed to be set up via environment variables.

    translate_client = translate.Client()
    translations = []

    for i, query_text in enumerate(queries):
        try:
            result = translate_client.translate(
                query_text, 
                target_language=target_language
            )
            translations.append({
                'original_query': query_text,
                'translated_query': result['translatedText'],
                'source_language': result['detectedSourceLanguage'],
                'target_language': target_language
            })
        except Exception as e:
            translations.append({
                'original_query': query_text,
                'error': str(e),
                'target_language': target_language
            })

    return {'translations': translations}
